using System;using System.IO;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Windows.Forms;
namespace CircuitoStudio {
public sealed class SwitchgearSelectionForm:Form {
Project project;Circuit circuit;string file;List<SwitchgearRating> items,visible;ComboBox family,poles;CheckBox loadSwitching;ListBox list;TextBox details;public bool Changed{get;private set;}
public SwitchgearSelectionForm(Project p,Circuit c,string library){project=p;circuit=c;file=library;items=File.Exists(file)?SwitchgearSelection.Import(file):new List<SwitchgearRating>();Text="Fusíveis e seccionadores — seleção nominal";Size=new Size(1160,730);MinimumSize=new Size(1050,650);Font=new Font("Segoe UI",10);StartPosition=FormStartPosition.CenterParent;var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=110,Padding=new Padding(8)};Add(top,"Importar CSV",Import);Add(top,"Modelo vazio CSV",Template);Add(top,"Selecionar dispositivo",Apply);Add(top,"Remover seleção",Remove);top.SetFlowBreak(top.Controls[top.Controls.Count-1],true);top.Controls.Add(new Label{Text="Família/categoria exigida",AutoSize=true,Margin=new Padding(5,8,5,0)});family=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=115};foreach(SwitchgearFamily x in Enum.GetValues(typeof(SwitchgearFamily)))family.Items.Add(x);top.Controls.Add(family);poles=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=100};foreach(PoleLayout x in Enum.GetValues(typeof(PoleLayout)))poles.Items.Add(BreakerSelection.PoleName(x));top.Controls.Add(poles);loadSwitching=new CheckBox{Text="Manobra sob carga exigida",Checked=true,AutoSize=true};top.Controls.Add(loadSwitching);var note=new Label{Dock=DockStyle.Top,Height=70,Padding=new Padding(10),Text=c.Id+"; "+c.Voltage+" V AC; "+p.Frequency+" Hz. Dispositivo adicional do circuito, a jusante da proteção primária quando houver.\r\nFusível gG: faixa completa; aM: sobrecarga separada pendente. Seccionador: manobra/isolação, sem interrupção de curto. A categoria exigida e a configuração física devem ser conferidas pelo projetista."};list=new ListBox{Dock=DockStyle.Top,Height=135,HorizontalScrollbar=true};details=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BackColor=Color.White};Controls.Add(details);Controls.Add(list);Controls.Add(note);Controls.Add(top);var binding=c.SwitchgearSelection;family.SelectedIndex=binding==null?0:(int)binding.RequiredFamily;poles.SelectedIndex=binding==null?(c.Phases==PhaseMode.Trifasico?(int)PoleLayout.ThreePole:(int)PoleLayout.OnePoleNeutral):(int)binding.RequiredPoles;loadSwitching.Checked=binding==null||binding.LoadSwitchingRequired;family.SelectedIndexChanged+=delegate{RefreshRows();};poles.SelectedIndexChanged+=delegate{RefreshDetails();};loadSwitching.CheckedChanged+=delegate{RefreshDetails();};list.SelectedIndexChanged+=delegate{RefreshDetails();};Shown+=delegate{details.SelectionStart=0;details.SelectionLength=0;details.ScrollToCaret();list.Focus();};RefreshRows();}
void Add(FlowLayoutPanel panel,string label,Action action){var b=new Button{Text=label,AutoSize=true};b.Click+=delegate{try{action();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Dispositivos",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};panel.Controls.Add(b);}
void RefreshRows(){visible=items.Where(x=>x.Family==(SwitchgearFamily)family.SelectedIndex).ToList();list.Items.Clear();foreach(var x in visible)list.Items.Add(x.Manufacturer+" / "+x.Reference+" / "+x.Family+" / "+BreakerSelection.PoleName(x.Poles)+" / "+x.VoltageV+" V / "+x.RatedA+" A / "+x.Source+" / "+x.DataVersion);if(list.Items.Count>0)list.SelectedIndex=0;else RefreshDetails();}
void RefreshDetails(){var study=Engineering.Analyze(project);var saved=SwitchgearSelection.Evaluate(project,study,circuit,circuit.SwitchgearSelection);details.Text="SELEÇÃO SALVA\r\n"+saved.Status+"\r\n"+saved.Detail;if(list.SelectedIndex>=0){var result=SwitchgearSelection.Evaluate(project,study,circuit,SwitchgearSelection.Candidate(circuit,visible[list.SelectedIndex],(SwitchgearFamily)family.SelectedIndex,(PoleLayout)poles.SelectedIndex,loadSwitching.Checked));details.AppendText("\r\n\r\nCANDIDATO\r\n"+result.Status+"\r\n"+result.Detail);}details.SelectionStart=0;details.SelectionLength=0;}
void Import(){using(var dialog=new OpenFileDialog{Filter="CSV|*.csv"})if(dialog.ShowDialog(this)==DialogResult.OK){var rows=SwitchgearSelection.Import(dialog.FileName);SwitchgearSelection.Export(rows,file);items=rows;RefreshRows();}}
void Template(){using(var dialog=new SaveFileDialog{Filter="CSV|*.csv",FileName="modelo-fusiveis-seccionadores.csv"})if(dialog.ShowDialog(this)==DialogResult.OK){if(String.Equals(Path.GetFullPath(dialog.FileName),Path.GetFullPath(file),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Use outro nome para preservar a biblioteca.");SwitchgearSelection.Export(new SwitchgearRating[0],dialog.FileName);}}
void Apply(){if(list.SelectedIndex<0)return;SwitchgearSelection.Apply(project,circuit,visible[list.SelectedIndex],(SwitchgearFamily)family.SelectedIndex,(PoleLayout)poles.SelectedIndex,loadSwitching.Checked);Changed=true;DialogResult=DialogResult.OK;Close();}
void Remove(){circuit.SwitchgearSelection=null;Changed=true;DialogResult=DialogResult.OK;Close();}
}
partial class Studio{void ConfigureSwitchgear(){if(circuit==null)throw new InvalidOperationException("Selecione um circuito.");using(var form=new SwitchgearSelectionForm(project,circuit,Path.Combine(userData,"fusiveis-seccionadores.csv")))if(form.ShowDialog(this)==DialogResult.OK&&form.Changed){Change();tabs.SelectedTab=studyPage;}}}
}
